-- Manual productivity writes: validation, versions, idempotency, and recurrence.
-- Design notes: docs/architecture/schema.md and docs/architecture/productivity.md
-- Do not edit this file after it is applied to a hosted project.

alter table public.events
  add column location text not null default '' check (char_length(location) <= 200);

alter table public.recurrence_series
  add column materialized_through date;

alter table public.idempotency_keys
  add column entity_type text,
  add column entity_id uuid,
  add column response jsonb;

alter table public.notes
  add column search_vector tsvector generated always as (
    to_tsvector('simple', title || ' ' || body)
  ) stored;

create index notes_search_idx on public.notes using gin (search_vector);

create unique index events_occurrence_identity_idx
  on public.events (owner_id, series_id, occurrence_on)
  where series_id is not null;

create or replace function public.clean_text(p_value text)
returns text
language sql
immutable
set search_path = public
as $$
  select trim(regexp_replace(coalesce(p_value, ''), '[\u0000-\u0008\u000B\u000C\u000E-\u001F]', '', 'g'));
$$;

create or replace function public.occurrence_date(
  p_start date,
  p_frequency text,
  p_interval integer,
  p_index integer
)
returns date
language sql
immutable
set search_path = public
as $$
  select case p_frequency
    when 'daily' then p_start + (p_index * p_interval)
    when 'weekly' then p_start + (p_index * p_interval * 7)
    when 'monthly' then (p_start + make_interval(months => p_index * p_interval))::date
    when 'yearly' then (p_start + make_interval(years => p_index * p_interval))::date
  end;
$$;

create or replace function public.take_idempotency(p_key text, p_hash text)
returns jsonb
language plpgsql
set search_path = public
as $$
declare
  owner uuid := auth.uid();
  existing public.idempotency_keys%rowtype;
  inserted boolean := false;
begin
  if owner is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_key is null or char_length(p_key) < 8 then
    return null;
  end if;
  delete from public.idempotency_keys
  where owner_id = owner and key = p_key and expires_at <= now();

  insert into public.idempotency_keys (owner_id, key, request_hash, response_status, expires_at)
  values (owner, p_key, p_hash, 200, now() + interval '24 hours')
  on conflict (owner_id, key) do nothing
  returning true into inserted;

  select * into existing
  from public.idempotency_keys
  where owner_id = owner and key = p_key
  for update;

  if existing.request_hash is distinct from p_hash then
    raise exception 'idempotency key reused' using errcode = 'P0003';
  end if;
  if not coalesce(inserted, false) then
    if existing.response is null then
      raise exception 'idempotency key reused' using errcode = 'P0003';
    end if;
    return existing.response;
  end if;
  return null;
end;
$$;

create or replace function public.finish_idempotency(
  p_key text,
  p_entity_type text,
  p_entity_id uuid,
  p_response jsonb
)
returns void
language plpgsql
set search_path = public
as $$
begin
  if p_key is null or char_length(p_key) < 8 then
    return;
  end if;
  update public.idempotency_keys
  set entity_type = p_entity_type,
      entity_id = p_entity_id,
      response = p_response
  where owner_id = auth.uid() and key = p_key;
end;
$$;

create or replace function public.require_text(p_value text, p_label text, p_max integer)
returns text
language plpgsql
immutable
set search_path = public
as $$
declare
  cleaned text := public.clean_text(p_value);
begin
  if char_length(cleaned) < 1 or char_length(cleaned) > p_max then
    raise exception 'invalid %', p_label using errcode = '22023';
  end if;
  return cleaned;
end;
$$;

create or replace function public.require_category(p_value text)
returns text
language plpgsql
immutable
set search_path = public
as $$
begin
  if p_value not in ('personal', 'home', 'work', 'admin', 'learning') then
    raise exception 'invalid category' using errcode = '22023';
  end if;
  return p_value;
end;
$$;

create or replace function public.materialize_series(
  p_series_id uuid,
  p_title text default 'Untitled',
  p_body text default '',
  p_category text default 'personal',
  p_location text default ''
)
returns integer
language plpgsql
set search_path = public
as $$
declare
  owner uuid := auth.uid();
  series public.recurrence_series%rowtype;
  n integer := 0;
  day date;
  last_day date;
  horizon date;
  written integer := 0;
  created integer := 0;
  start_at timestamptz;
  end_at timestamptz;
begin
  if owner is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  select * into series
  from public.recurrence_series
  where id = p_series_id and owner_id = owner and deleted_at is null
  for update;
  if not found then
    raise exception 'not found' using errcode = 'P0004';
  end if;

  horizon := (series.starts_on + interval '18 months')::date;
  loop
    day := public.occurrence_date(series.starts_on, series.frequency, series.interval_count, n);
    exit when day is null or n > 400;
    exit when series.until_on is not null and day > series.until_on;
    exit when series.occurrence_count is not null and n >= series.occurrence_count;
    exit when series.until_on is null and series.occurrence_count is null and day > horizon;
    last_day := day;

    if series.all_day then
      insert into public.events (
        owner_id, series_id, occurrence_on, title, body, category, all_day,
        starts_on, ends_on, timezone, location
      )
      select
        owner, series.id, day, p_title, p_body, p_category, true,
        day, day, series.timezone, p_location
      where not exists (
        select 1 from public.events e
        where e.owner_id = owner and e.series_id = series.id and e.occurrence_on = day
      )
      and not exists (
        select 1 from public.recurrence_exceptions x
        where x.owner_id = owner and x.series_id = series.id and x.occurrence_on = day
          and x.kind in ('skip', 'cancel')
      );
    else
      start_at := (day + series.local_start_time) at time zone series.timezone;
      end_at := start_at + make_interval(mins => coalesce(series.duration_minutes, 60));
      insert into public.events (
        owner_id, series_id, occurrence_on, title, body, category, all_day,
        starts_at, ends_at, timezone, location
      )
      select
        owner, series.id, day, p_title, p_body, p_category, false,
        start_at, end_at, series.timezone, p_location
      where not exists (
        select 1 from public.events e
        where e.owner_id = owner and e.series_id = series.id and e.occurrence_on = day
      )
      and not exists (
        select 1 from public.recurrence_exceptions x
        where x.owner_id = owner and x.series_id = series.id and x.occurrence_on = day
          and x.kind in ('skip', 'cancel')
      );
    end if;
    GET DIAGNOSTICS created = ROW_COUNT;
    written := written + created;
    n := n + 1;
  end loop;

  update public.recurrence_series
  set materialized_through = coalesce(last_day, series.starts_on)
  where id = series.id and owner_id = owner;
  return written;
end;
$$;

create or replace function public.page_limit(p_limit integer)
returns integer
language sql
immutable
set search_path = public
as $$
  select least(greatest(coalesce(p_limit, 50), 1), 100);
$$;

create or replace function public.require_zone(p_timezone text)
returns text
language plpgsql
stable
set search_path = public
as $$
begin
  if p_timezone is null or char_length(p_timezone) < 1 or char_length(p_timezone) > 80 then
    raise exception 'invalid timezone' using errcode = '22023';
  end if;
  if not exists (select 1 from pg_timezone_names where name = p_timezone) then
    raise exception 'invalid timezone' using errcode = '22023';
  end if;
  return p_timezone;
end;
$$;

create or replace function public.create_work_item(
  p_title text,
  p_body text,
  p_category text,
  p_severity text,
  p_due_on date,
  p_due_at timestamptz,
  p_estimate_minutes integer,
  p_idempotency_key text
)
returns jsonb
language plpgsql
set search_path = public
as $$
declare
  owner uuid := auth.uid();
  hash text;
  replay jsonb;
  created public.work_items%rowtype;
  response jsonb;
begin
  if owner is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_due_on is not null and p_due_at is not null then
    raise exception 'invalid deadline' using errcode = '22023';
  end if;
  if p_severity not in ('critical', 'high', 'medium', 'low') then
    raise exception 'invalid severity' using errcode = '22023';
  end if;
  if p_estimate_minutes is not null and p_estimate_minutes not between 0 and 20160 then
    raise exception 'invalid estimate' using errcode = '22023';
  end if;
  if char_length(public.clean_text(p_body)) > 20000 then
    raise exception 'invalid body' using errcode = '22023';
  end if;
  hash := md5(concat_ws('|', 'create_work_item', p_title, p_body, p_category, p_severity, p_due_on::text, p_due_at::text, p_estimate_minutes::text));
  replay := public.take_idempotency(p_idempotency_key, hash);
  if replay is not null then
    return replay;
  end if;
  insert into public.work_items (
    owner_id, title, body, category, severity, due_on, due_at, estimate_minutes
  )
  values (
    owner,
    public.require_text(p_title, 'title', 200),
    public.clean_text(p_body),
    public.require_category(p_category),
    p_severity,
    p_due_on,
    p_due_at,
    p_estimate_minutes
  )
  returning * into created;
  response := jsonb_build_object('work_item', to_jsonb(created));
  perform public.finish_idempotency(p_idempotency_key, 'work_item', created.id, response);
  return response;
end;
$$;

create or replace function public.update_work_item(
  p_id uuid,
  p_expected_version integer,
  p_title text,
  p_body text,
  p_category text,
  p_severity text,
  p_due_on date,
  p_due_at timestamptz,
  p_estimate_minutes integer,
  p_idempotency_key text
)
returns jsonb
language plpgsql
set search_path = public
as $$
declare
  owner uuid := auth.uid();
  hash text;
  replay jsonb;
  current public.work_items%rowtype;
  updated public.work_items%rowtype;
  response jsonb;
begin
  if owner is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_due_on is not null and p_due_at is not null then
    raise exception 'invalid deadline' using errcode = '22023';
  end if;
  if p_severity not in ('critical', 'high', 'medium', 'low') then
    raise exception 'invalid severity' using errcode = '22023';
  end if;
  if p_estimate_minutes is not null and p_estimate_minutes not between 0 and 20160 then
    raise exception 'invalid estimate' using errcode = '22023';
  end if;
  if char_length(public.clean_text(p_body)) > 20000 then
    raise exception 'invalid body' using errcode = '22023';
  end if;
  hash := md5(concat_ws('|', 'update_work_item', p_id::text, p_expected_version::text, p_title, p_body, p_category, p_severity, p_due_on::text, p_due_at::text, p_estimate_minutes::text));
  replay := public.take_idempotency(p_idempotency_key, hash);
  if replay is not null then
    return replay;
  end if;
  select * into current
  from public.work_items
  where id = p_id and owner_id = owner and deleted_at is null
  for update;
  if not found then
    raise exception 'not found' using errcode = 'P0004';
  end if;
  if current.version <> p_expected_version then
    raise exception 'version conflict' using errcode = 'P0002';
  end if;
  update public.work_items
  set title = public.require_text(p_title, 'title', 200),
      body = public.clean_text(p_body),
      category = public.require_category(p_category),
      severity = p_severity,
      due_on = p_due_on,
      due_at = p_due_at,
      estimate_minutes = p_estimate_minutes
  where id = current.id and owner_id = owner
  returning * into updated;
  response := jsonb_build_object('work_item', to_jsonb(updated));
  perform public.finish_idempotency(p_idempotency_key, 'work_item', updated.id, response);
  return response;
end;
$$;

create or replace function public.set_work_item_status(
  p_id uuid,
  p_expected_version integer,
  p_status text,
  p_idempotency_key text
)
returns jsonb
language plpgsql
set search_path = public
as $$
declare
  owner uuid := auth.uid();
  hash text;
  replay jsonb;
  current public.work_items%rowtype;
  updated public.work_items%rowtype;
  response jsonb;
begin
  if owner is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_status not in ('open', 'done', 'cancelled') then
    raise exception 'invalid status' using errcode = '22023';
  end if;
  hash := md5(concat_ws('|', 'set_work_item_status', p_id::text, p_expected_version::text, p_status));
  replay := public.take_idempotency(p_idempotency_key, hash);
  if replay is not null then
    return replay;
  end if;
  select * into current
  from public.work_items
  where id = p_id and owner_id = owner and deleted_at is null
  for update;
  if not found then
    raise exception 'not found' using errcode = 'P0004';
  end if;
  if current.version <> p_expected_version then
    raise exception 'version conflict' using errcode = 'P0002';
  end if;
  update public.work_items
  set status = p_status,
      completed_at = case when p_status = 'done' then coalesce(current.completed_at, now()) else null end
  where id = current.id and owner_id = owner
  returning * into updated;
  response := jsonb_build_object('work_item', to_jsonb(updated));
  perform public.finish_idempotency(p_idempotency_key, 'work_item', updated.id, response);
  return response;
end;
$$;

