create or replace function public.restore_work_item(
  p_id uuid,
  p_expected_version integer,
  p_idempotency_key text
)
returns jsonb
language plpgsql
set search_path = public
as $$
declare
  owner uuid := auth.uid();
  hash text;
  replay jsonb;
  current public.work_items%rowtype;
  updated public.work_items%rowtype;
  response jsonb;
begin
  if owner is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  hash := md5(concat_ws('|', 'restore_work_item', p_id::text, p_expected_version::text));
  replay := public.take_idempotency(p_idempotency_key, hash);
  if replay is not null then
    return replay;
  end if;
  select * into current
  from public.work_items
  where id = p_id and owner_id = owner and deleted_at is not null
  for update;
  if not found then
    raise exception 'not found' using errcode = 'P0004';
  end if;
  if current.version <> p_expected_version then
    raise exception 'version conflict' using errcode = 'P0002';
  end if;
  update public.work_items
  set deleted_at = null
  where id = current.id and owner_id = owner
  returning * into updated;
  response := jsonb_build_object('work_item', to_jsonb(updated));
  perform public.finish_idempotency(p_idempotency_key, 'work_item', updated.id, response);
  return response;
end;
$$;

create or replace function public.event_bounds(
  p_all_day boolean,
  p_starts_on date,
  p_ends_on date,
  p_local_start time,
  p_local_end time,
  p_timezone text
)
returns table (starts_on date, ends_on date, starts_at timestamptz, ends_at timestamptz, duration_minutes integer)
language plpgsql
stable
set search_path = public
as $$
begin
  if p_all_day then
    if p_starts_on is null or p_ends_on is null or p_ends_on < p_starts_on then
      raise exception 'invalid schedule' using errcode = '22023';
    end if;
    starts_on := p_starts_on;
    ends_on := p_ends_on;
    starts_at := null;
    ends_at := null;
    duration_minutes := null;
    return next;
    return;
  end if;
  if p_starts_on is null or p_local_start is null or p_local_end is null or p_local_end <= p_local_start then
    raise exception 'invalid schedule' using errcode = '22023';
  end if;
  starts_on := null;
  ends_on := null;
  starts_at := (p_starts_on + p_local_start) at time zone p_timezone;
  ends_at := (p_starts_on + p_local_end) at time zone p_timezone;
  duration_minutes := (extract(epoch from (p_local_end - p_local_start)) / 60)::integer;
  if duration_minutes < 1 or duration_minutes > 1440 or ends_at <= starts_at then
    raise exception 'invalid schedule' using errcode = '22023';
  end if;
  return next;
end;
$$;

create or replace function public.create_event(
  p_title text,
  p_body text,
  p_category text,
  p_all_day boolean,
  p_starts_on date,
  p_ends_on date,
  p_local_start time,
  p_local_end time,
  p_timezone text,
  p_location text,
  p_frequency text,
  p_interval integer,
  p_until date,
  p_count integer,
  p_idempotency_key text
)
returns jsonb
language plpgsql
set search_path = public
as $$
declare
  owner uuid := auth.uid();
  zone text;
  hash text;
  replay jsonb;
  bounds record;
  created public.events%rowtype;
  series public.recurrence_series%rowtype;
  response jsonb;
  location text;
  title text;
  body text;
  category text;
begin
  if owner is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_frequency is not null and p_frequency not in ('daily', 'weekly', 'monthly', 'yearly') then
    raise exception 'invalid frequency' using errcode = '22023';
  end if;
  if p_until is not null and p_count is not null then
    raise exception 'invalid recurrence end' using errcode = '22023';
  end if;
  if coalesce(p_interval, 1) < 1 then
    raise exception 'invalid interval' using errcode = '22023';
  end if;
  zone := public.require_zone(p_timezone);
  title := public.require_text(p_title, 'title', 200);
  body := public.clean_text(p_body);
  if char_length(body) > 20000 then
    raise exception 'invalid body' using errcode = '22023';
  end if;
  category := public.require_category(p_category);
  location := public.clean_text(p_location);
  if char_length(location) > 200 then
    raise exception 'invalid location' using errcode = '22023';
  end if;
  select * into bounds
  from public.event_bounds(p_all_day, p_starts_on, p_ends_on, p_local_start, p_local_end, zone);
  hash := md5(concat_ws('|', 'create_event', title, body, category, p_all_day::text, p_starts_on::text, p_ends_on::text, p_local_start::text, p_local_end::text, zone, location, p_frequency, coalesce(p_interval, 1)::text, p_until::text, p_count::text));
  replay := public.take_idempotency(p_idempotency_key, hash);
  if replay is not null then
    return replay;
  end if;

  if p_frequency is null then
    insert into public.events (
      owner_id, title, body, category, all_day, starts_on, ends_on, starts_at, ends_at, timezone, location
    )
    values (
      owner, title, body, category, p_all_day, bounds.starts_on, bounds.ends_on, bounds.starts_at, bounds.ends_at, zone, location
    )
    returning * into created;
    response := jsonb_build_object('event', to_jsonb(created));
    perform public.finish_idempotency(p_idempotency_key, 'event', created.id, response);
    return response;
  end if;

  insert into public.recurrence_series (
    owner_id, frequency, interval_count, timezone, starts_on, until_on, occurrence_count,
    local_start_time, duration_minutes, all_day
  )
  values (
    owner, p_frequency, coalesce(p_interval, 1), zone, p_starts_on, p_until, p_count,
    case when p_all_day then null else p_local_start end,
    bounds.duration_minutes,
    p_all_day
  )
  returning * into series;
  perform public.materialize_series(series.id, title, body, category, location);
  select * into created
  from public.events
  where owner_id = owner and series_id = series.id and occurrence_on = p_starts_on;
  response := jsonb_build_object('event', to_jsonb(created), 'series', to_jsonb(series));
  perform public.finish_idempotency(p_idempotency_key, 'event', created.id, response);
  return response;
end;
$$;


create or replace function public.update_event(
  p_id uuid,
  p_expected_version integer,
  p_scope text,
  p_title text,
  p_body text,
  p_category text,
  p_all_day boolean,
  p_starts_on date,
  p_ends_on date,
  p_local_start time,
  p_local_end time,
  p_timezone text,
  p_location text,
  p_idempotency_key text
)
returns jsonb
language plpgsql
set search_path = public
as $$
#variable_conflict use_variable
declare
  owner uuid := auth.uid();
  hash text;
  replay jsonb;
  current public.events%rowtype;
  updated public.events%rowtype;
  series public.recurrence_series%rowtype;
  new_series uuid;
  zone text;
  title text;
  body text;
  category text;
  location text;
  duration integer;
  response jsonb;
  moved integer;
begin
  if owner is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_scope not in ('one', 'following', 'all') then
    raise exception 'invalid scope' using errcode = '22023';
  end if;
  zone := public.require_zone(p_timezone);
  title := public.require_text(p_title, 'title', 200);
  body := public.clean_text(p_body);
  if char_length(body) > 20000 then
    raise exception 'invalid body' using errcode = '22023';
  end if;
  category := public.require_category(p_category);
  location := public.clean_text(p_location);
  if char_length(location) > 200 then
    raise exception 'invalid location' using errcode = '22023';
  end if;
  if not p_all_day and (p_local_start is null or p_local_end is null or p_local_end <= p_local_start) then
    raise exception 'invalid schedule' using errcode = '22023';
  end if;
  duration := case
    when p_all_day then null
    else (extract(epoch from (p_local_end - p_local_start)) / 60)::integer
  end;
  hash := md5(concat_ws('|', 'update_event', p_id::text, p_expected_version::text, p_scope, title, body, category, p_all_day::text, p_starts_on::text, p_ends_on::text, p_local_start::text, p_local_end::text, zone, location));
  replay := public.take_idempotency(p_idempotency_key, hash);
  if replay is not null then
    return replay;
  end if;

  select * into current
  from public.events
  where id = p_id and owner_id = owner and deleted_at is null
  for update;
  if not found then
    raise exception 'not found' using errcode = 'P0004';
  end if;
  if current.version <> p_expected_version then
    raise exception 'version conflict' using errcode = 'P0002';
  end if;

  if current.series_id is null or p_scope = 'one' then
    if current.series_id is null then
      if p_all_day then
        if p_starts_on is null or p_ends_on is null or p_ends_on < p_starts_on then
          raise exception 'invalid schedule' using errcode = '22023';
        end if;
        update public.events
        set title = title, body = body, category = category, location = location,
            timezone = zone, all_day = true,
            starts_on = p_starts_on, ends_on = p_ends_on, starts_at = null, ends_at = null
        where id = current.id and owner_id = owner
        returning * into updated;
      else
        update public.events
        set title = title, body = body, category = category, location = location,
            timezone = zone, all_day = false, starts_on = null, ends_on = null,
            starts_at = (p_starts_on + p_local_start) at time zone zone,
            ends_at = (p_starts_on + p_local_end) at time zone zone
        where id = current.id and owner_id = owner
        returning * into updated;
      end if;
    else
      if p_all_day then
        update public.events
        set title = title, body = body, category = category, location = location,
            timezone = zone, all_day = true,
            starts_on = current.occurrence_on, ends_on = current.occurrence_on,
            starts_at = null, ends_at = null
        where id = current.id and owner_id = owner
        returning * into updated;
      else
        update public.events
        set title = title, body = body, category = category, location = location,
            timezone = zone, all_day = false, starts_on = null, ends_on = null,
            starts_at = (current.occurrence_on + p_local_start) at time zone zone,
            ends_at = (current.occurrence_on + p_local_end) at time zone zone
        where id = current.id and owner_id = owner
        returning * into updated;
      end if;
      insert into public.recurrence_exceptions (owner_id, series_id, occurrence_on, kind)
      values (owner, current.series_id, current.occurrence_on, 'override')
      on conflict (owner_id, series_id, occurrence_on)
      do update set kind = 'override';
    end if;
    response := jsonb_build_object('event', to_jsonb(updated));
    perform public.finish_idempotency(p_idempotency_key, 'event', updated.id, response);
    return response;
  end if;

  select * into series
  from public.recurrence_series
  where id = current.series_id and owner_id = owner and deleted_at is null
  for update;
  if not found then
    raise exception 'not found' using errcode = 'P0004';
  end if;

  if p_scope = 'following' then
    insert into public.recurrence_series (
      owner_id, frequency, interval_count, timezone, starts_on, until_on, occurrence_count,
      local_start_time, duration_minutes, all_day
    )
    values (
      owner, series.frequency, series.interval_count, zone, current.occurrence_on,
      case when series.occurrence_count is null then series.until_on else null end,
      null,
      case when p_all_day then null else p_local_start end,
      duration,
      p_all_day
    )
    returning id into new_series;

    update public.events e
    set series_id = new_series,
        title = case
          when e.id = current.id or not exists (
            select 1 from public.recurrence_exceptions x
            where x.owner_id = owner and x.series_id = series.id
              and x.occurrence_on = e.occurrence_on and x.kind = 'override'
          ) then title else e.title end,
        body = case when e.id = current.id or not exists (
            select 1 from public.recurrence_exceptions x
            where x.owner_id = owner and x.series_id = series.id
              and x.occurrence_on = e.occurrence_on and x.kind = 'override'
          ) then body else e.body end,
        category = case when e.id = current.id or not exists (
            select 1 from public.recurrence_exceptions x
            where x.owner_id = owner and x.series_id = series.id
              and x.occurrence_on = e.occurrence_on and x.kind = 'override'
          ) then category else e.category end,
        location = case when e.id = current.id or not exists (
            select 1 from public.recurrence_exceptions x
            where x.owner_id = owner and x.series_id = series.id
              and x.occurrence_on = e.occurrence_on and x.kind = 'override'
          ) then location else e.location end,
        timezone = zone,
        all_day = case when e.id = current.id or not exists (
            select 1 from public.recurrence_exceptions x
            where x.owner_id = owner and x.series_id = series.id
              and x.occurrence_on = e.occurrence_on and x.kind = 'override'
          ) then p_all_day else e.all_day end,
        starts_on = case
          when e.id <> current.id and exists (
            select 1 from public.recurrence_exceptions x
            where x.owner_id = owner and x.series_id = series.id
              and x.occurrence_on = e.occurrence_on and x.kind = 'override'
          ) then e.starts_on
          when p_all_day then e.occurrence_on else null end,
        ends_on = case
          when e.id <> current.id and exists (
            select 1 from public.recurrence_exceptions x
            where x.owner_id = owner and x.series_id = series.id
              and x.occurrence_on = e.occurrence_on and x.kind = 'override'
          ) then e.ends_on
          when p_all_day then e.occurrence_on else null end,
        starts_at = case
          when e.id <> current.id and exists (
            select 1 from public.recurrence_exceptions x
            where x.owner_id = owner and x.series_id = series.id
              and x.occurrence_on = e.occurrence_on and x.kind = 'override'
          ) then e.starts_at
          when p_all_day then null
          else (e.occurrence_on + p_local_start) at time zone zone end,
        ends_at = case
          when e.id <> current.id and exists (
            select 1 from public.recurrence_exceptions x
            where x.owner_id = owner and x.series_id = series.id
              and x.occurrence_on = e.occurrence_on and x.kind = 'override'
          ) then e.ends_at
          when p_all_day then null
          else (e.occurrence_on + p_local_end) at time zone zone end
    where e.owner_id = owner and e.series_id = series.id
      and e.occurrence_on >= current.occurrence_on and e.deleted_at is null;

    update public.recurrence_exceptions
    set series_id = new_series
    where owner_id = owner and series_id = series.id and occurrence_on >= current.occurrence_on;
    delete from public.recurrence_exceptions
    where owner_id = owner and series_id = new_series and occurrence_on = current.occurrence_on and kind = 'override';

    select count(*) into moved
    from public.events
    where owner_id = owner and series_id = series.id and deleted_at is null;
    if series.occurrence_count is not null then
      update public.recurrence_series
      set occurrence_count = greatest(moved, 1), until_on = null
      where id = series.id and owner_id = owner;
      update public.recurrence_series
      set occurrence_count = (
        select count(*) from public.events
        where owner_id = owner and series_id = new_series and deleted_at is null
      ),
      until_on = null
      where id = new_series and owner_id = owner;
    else
      if current.occurrence_on - 1 < series.starts_on then
        update public.recurrence_series
        set deleted_at = now()
        where id = series.id and owner_id = owner;
      else
        update public.recurrence_series
        set until_on = current.occurrence_on - 1
        where id = series.id and owner_id = owner;
      end if;
    end if;
    if moved = 0 then
      update public.recurrence_series set deleted_at = now() where id = series.id and owner_id = owner;
    end if;
    select * into updated from public.events where id = current.id and owner_id = owner;
    response := jsonb_build_object('event', to_jsonb(updated), 'series_id', new_series);
    perform public.finish_idempotency(p_idempotency_key, 'event', updated.id, response);
    return response;
  end if;

  update public.recurrence_series
  set timezone = zone,
      all_day = p_all_day,
      local_start_time = case when p_all_day then null else p_local_start end,
      duration_minutes = duration
  where id = series.id and owner_id = owner;
  delete from public.recurrence_exceptions
  where owner_id = owner and series_id = series.id and occurrence_on = current.occurrence_on and kind = 'override';

  update public.events e
  set title = title, body = body, category = category, location = location,
      timezone = zone, all_day = p_all_day,
      starts_on = case when p_all_day then e.occurrence_on else null end,
      ends_on = case when p_all_day then e.occurrence_on else null end,
      starts_at = case when p_all_day then null else (e.occurrence_on + p_local_start) at time zone zone end,
      ends_at = case when p_all_day then null else (e.occurrence_on + p_local_end) at time zone zone end
  where e.owner_id = owner and e.series_id = series.id and e.deleted_at is null
    and not exists (
      select 1 from public.recurrence_exceptions x
      where x.owner_id = owner and x.series_id = series.id
        and x.occurrence_on = e.occurrence_on and x.kind = 'override'
    );
  select * into updated from public.events where id = current.id and owner_id = owner;
  response := jsonb_build_object('event', to_jsonb(updated), 'series_id', series.id);
  perform public.finish_idempotency(p_idempotency_key, 'event', updated.id, response);
  return response;
end;
$$;

create or replace function public.soft_delete_event(
  p_id uuid,
  p_expected_version integer,
  p_scope text,
  p_idempotency_key text
)
returns jsonb
language plpgsql
set search_path = public
as $$
declare
  owner uuid := auth.uid();
  hash text;
  replay jsonb;
  current public.events%rowtype;
  response jsonb;
  series public.recurrence_series%rowtype;
begin
  if owner is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_scope not in ('one', 'following', 'all') then
    raise exception 'invalid scope' using errcode = '22023';
  end if;
  hash := md5(concat_ws('|', 'soft_delete_event', p_id::text, p_expected_version::text, p_scope));
  replay := public.take_idempotency(p_idempotency_key, hash);
  if replay is not null then
    return replay;
  end if;
  select * into current
  from public.events
  where id = p_id and owner_id = owner and deleted_at is null
  for update;
  if not found then
    raise exception 'not found' using errcode = 'P0004';
  end if;
  if current.version <> p_expected_version then
    raise exception 'version conflict' using errcode = 'P0002';
  end if;

  if current.series_id is null or p_scope = 'one' then
    update public.events set deleted_at = now() where id = current.id and owner_id = owner;
    if current.series_id is not null then
      insert into public.recurrence_exceptions (owner_id, series_id, occurrence_on, kind)
      values (owner, current.series_id, current.occurrence_on, 'cancel')
      on conflict (owner_id, series_id, occurrence_on)
      do update set kind = 'cancel';
    end if;
  elsif p_scope = 'following' then
    insert into public.recurrence_exceptions (owner_id, series_id, occurrence_on, kind)
    select owner, current.series_id, e.occurrence_on, 'cancel'
    from public.events e
    where e.owner_id = owner and e.series_id = current.series_id
      and e.occurrence_on >= current.occurrence_on and e.deleted_at is null
    on conflict (owner_id, series_id, occurrence_on)
    do update set kind = 'cancel';
    update public.events
    set deleted_at = now()
    where owner_id = owner and series_id = current.series_id
      and occurrence_on >= current.occurrence_on and deleted_at is null;
    select * into series from public.recurrence_series where id = current.series_id and owner_id = owner;
    if series.occurrence_count is null and current.occurrence_on - 1 >= series.starts_on then
      update public.recurrence_series
      set until_on = current.occurrence_on - 1
      where id = series.id and owner_id = owner;
    elsif series.occurrence_count is not null then
      if (
        select count(*) from public.events
        where owner_id = owner and series_id = series.id and deleted_at is null
      ) = 0 then
        update public.recurrence_series set deleted_at = now() where id = series.id and owner_id = owner;
      else
        update public.recurrence_series
        set occurrence_count = (
          select count(*) from public.events
          where owner_id = owner and series_id = series.id and deleted_at is null
        )
        where id = series.id and owner_id = owner;
      end if;
    else
      update public.recurrence_series set deleted_at = now() where id = series.id and owner_id = owner;
    end if;
  else
    update public.events
    set deleted_at = now()
    where owner_id = owner and series_id = current.series_id and deleted_at is null;
    update public.recurrence_series
    set deleted_at = now()
    where id = current.series_id and owner_id = owner;
  end if;

  select * into current from public.events where id = p_id and owner_id = owner;
  response := jsonb_build_object('event', to_jsonb(current));
  perform public.finish_idempotency(p_idempotency_key, 'event', current.id, response);
  return response;
end;
$$;

create or replace function public.create_note(
  p_title text,
  p_body text,
  p_work_item_id uuid,
  p_event_id uuid,
  p_idempotency_key text
)
returns jsonb
language plpgsql
set search_path = public
as $$
declare
  owner uuid := auth.uid();
  hash text;
  replay jsonb;
  created public.notes%rowtype;
  response jsonb;
  title text;
  body text;
begin
  if owner is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_work_item_id is not null and p_event_id is not null then
    raise exception 'invalid parent' using errcode = '22023';
  end if;
  title := public.require_text(p_title, 'title', 200);
  body := public.require_text(p_body, 'body', 20000);
  hash := md5(concat_ws('|', 'create_note', title, body, p_work_item_id::text, p_event_id::text));
  replay := public.take_idempotency(p_idempotency_key, hash);
  if replay is not null then
    return replay;
  end if;
  insert into public.notes (owner_id, title, body, work_item_id, event_id)
  values (owner, title, body, p_work_item_id, p_event_id)
  returning * into created;
  response := jsonb_build_object('note', to_jsonb(created));
  perform public.finish_idempotency(p_idempotency_key, 'note', created.id, response);
  return response;
end;
$$;

