create or replace function public.create_reminder(
  p_title text,
  p_work_item_id uuid,
  p_event_id uuid,
  p_remind_at timestamptz,
  p_remind_on date,
  p_offset_minutes integer,
  p_channel text,
  p_idempotency_key text
)
returns jsonb
language plpgsql
set search_path = public
as $$
declare
  owner uuid := auth.uid();
  hash text;
  replay jsonb;
  created public.reminders%rowtype;
  response jsonb;
begin
  if owner is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if num_nonnulls(p_remind_at, p_remind_on, p_offset_minutes) <> 1 then
    raise exception 'invalid schedule' using errcode = '22023';
  end if;
  if p_offset_minutes is not null and p_event_id is null then
    raise exception 'invalid schedule' using errcode = '22023';
  end if;
  if p_channel not in ('in_app', 'email', 'push') then
    raise exception 'invalid channel' using errcode = '22023';
  end if;
  if p_offset_minutes is not null and p_offset_minutes not between -10080 and 10080 then
    raise exception 'invalid schedule' using errcode = '22023';
  end if;
  hash := md5(concat_ws('|', 'create_reminder', p_title, p_work_item_id::text, p_event_id::text, p_remind_at::text, p_remind_on::text, p_offset_minutes::text, p_channel));
  replay := public.take_idempotency(p_idempotency_key, hash);
  if replay is not null then
    return replay;
  end if;
  insert into public.reminders (
    owner_id, title, work_item_id, event_id, remind_at, remind_on, offset_minutes, channel
  )
  values (
    owner, public.require_text(p_title, 'title', 200), p_work_item_id, p_event_id,
    p_remind_at, p_remind_on, p_offset_minutes, p_channel
  )
  returning * into created;
  response := jsonb_build_object('reminder', to_jsonb(created));
  perform public.finish_idempotency(p_idempotency_key, 'reminder', created.id, response);
  return response;
end;
$$;

create or replace function public.update_reminder(
  p_id uuid,
  p_expected_version integer,
  p_title text,
  p_work_item_id uuid,
  p_event_id uuid,
  p_remind_at timestamptz,
  p_remind_on date,
  p_offset_minutes integer,
  p_channel text,
  p_status text,
  p_idempotency_key text
)
returns jsonb
language plpgsql
set search_path = public
as $$
declare
  owner uuid := auth.uid();
  hash text;
  replay jsonb;
  current public.reminders%rowtype;
  updated public.reminders%rowtype;
  response jsonb;
begin
  if owner is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if num_nonnulls(p_remind_at, p_remind_on, p_offset_minutes) <> 1 then
    raise exception 'invalid schedule' using errcode = '22023';
  end if;
  if p_offset_minutes is not null and p_event_id is null then
    raise exception 'invalid schedule' using errcode = '22023';
  end if;
  if p_channel not in ('in_app', 'email', 'push') or p_status not in ('active', 'cancelled') then
    raise exception 'invalid reminder' using errcode = '22023';
  end if;
  hash := md5(concat_ws('|', 'update_reminder', p_id::text, p_expected_version::text, p_title, p_work_item_id::text, p_event_id::text, p_remind_at::text, p_remind_on::text, p_offset_minutes::text, p_channel, p_status));
  replay := public.take_idempotency(p_idempotency_key, hash);
  if replay is not null then
    return replay;
  end if;
  select * into current from public.reminders
  where id = p_id and owner_id = owner and deleted_at is null
  for update;
  if not found then
    raise exception 'not found' using errcode = 'P0004';
  end if;
  if current.version <> p_expected_version then
    raise exception 'version conflict' using errcode = 'P0002';
  end if;
  update public.reminders
  set title = public.require_text(p_title, 'title', 200),
      work_item_id = p_work_item_id,
      event_id = p_event_id,
      remind_at = p_remind_at,
      remind_on = p_remind_on,
      offset_minutes = p_offset_minutes,
      channel = p_channel,
      status = p_status
  where id = current.id and owner_id = owner
  returning * into updated;
  response := jsonb_build_object('reminder', to_jsonb(updated));
  perform public.finish_idempotency(p_idempotency_key, 'reminder', updated.id, response);
  return response;
end;
$$;

