  returning * into updated;
  response := jsonb_build_object('reminder', to_jsonb(updated));
  perform public.finish_idempotency(p_idempotency_key, 'reminder', updated.id, response);
  return response;
end;
$$;

create or replace function public.list_work_items(
  p_limit integer,
  p_cursor_created timestamptz,
  p_cursor_id uuid,
  p_status text
)
returns jsonb
language plpgsql
stable
set search_path = public
as $$
declare
  owner uuid := auth.uid();
  lim integer := public.page_limit(p_limit);
  payload jsonb;
begin
  if owner is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  with page as (
    select *
    from public.work_items
    where owner_id = owner and deleted_at is null
      and (p_status is null or status = p_status)
      and (
        p_cursor_created is null
        or (created_at, id) < (p_cursor_created, p_cursor_id)
      )
    order by created_at desc, id desc
    limit lim
  )
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(to_jsonb(page) order by created_at desc, id desc) from page), '[]'::jsonb),
    'next_created_at', case when (select count(*) from page) = lim then (select created_at from page order by created_at asc, id asc limit 1) else null end,
    'next_id', case when (select count(*) from page) = lim then (select id from page order by created_at asc, id asc limit 1) else null end
  )
  into payload;
  return payload;
end;
$$;

create or replace function public.list_events_between(p_start date, p_end date)
returns jsonb
language plpgsql
stable
set search_path = public
as $$
declare
  owner uuid := auth.uid();
  payload jsonb;
begin
  if owner is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_start is null or p_end is null or p_end < p_start or p_end > p_start + 400 then
    raise exception 'invalid range' using errcode = '22023';
  end if;
  select coalesce(jsonb_agg(to_jsonb(e) order by e.starts_at nulls last, e.starts_on, e.id), '[]'::jsonb)
  into payload
  from public.events e
  where e.owner_id = owner and e.deleted_at is null
    and (
      (e.all_day and e.starts_on <= p_end and e.ends_on >= p_start)
      or (
        not e.all_day
        and e.starts_at < ((p_end + 2)::timestamp at time zone 'UTC')
        and e.ends_at > ((p_start - 2)::timestamp at time zone 'UTC')
      )
    );
  return jsonb_build_object('items', payload);
end;
$$;

create or replace function public.list_notes(p_limit integer, p_query text)
returns jsonb
language plpgsql
stable
set search_path = public
as $$
declare
  owner uuid := auth.uid();
  lim integer := public.page_limit(p_limit);
  needle text := public.clean_text(coalesce(p_query, ''));
  payload jsonb;
begin
  if owner is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(to_jsonb(n) order by n.updated_at desc, n.id desc), '[]'::jsonb)
  into payload
  from (
    select notes.*
    from public.notes
    where notes.owner_id = owner and notes.deleted_at is null
      and (
        notes.work_item_id is null or exists (
          select 1 from public.work_items w
          where w.owner_id = owner and w.id = notes.work_item_id and w.deleted_at is null
        )
      )
      and (
        notes.event_id is null or exists (
          select 1 from public.events e
          where e.owner_id = owner and e.id = notes.event_id and e.deleted_at is null
        )
      )
      and (
        needle = ''
        or notes.search_vector @@ plainto_tsquery('simple', needle)
        or notes.title ilike '%' || replace(replace(replace(needle, '\', '\\'), '%', '\%'), '_', '\_') || '%' escape '\'
      )
    order by notes.updated_at desc, notes.id desc
    limit lim
  ) n;
  return jsonb_build_object('items', payload);
end;
$$;

create or replace function public.list_reminders(p_limit integer)
returns jsonb
language plpgsql
stable
set search_path = public
as $$
declare
  owner uuid := auth.uid();
  lim integer := public.page_limit(p_limit);
  payload jsonb;
begin
  if owner is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(to_jsonb(r) order by r.created_at desc, r.id desc), '[]'::jsonb)
  into payload
  from (
    select reminders.*
    from public.reminders
    where reminders.owner_id = owner and reminders.deleted_at is null
      and (
        reminders.work_item_id is null or exists (
          select 1 from public.work_items w
          where w.owner_id = owner and w.id = reminders.work_item_id and w.deleted_at is null
        )
      )
      and (
        reminders.event_id is null or exists (
          select 1 from public.events e
          where e.owner_id = owner and e.id = reminders.event_id and e.deleted_at is null
        )
      )
    order by reminders.created_at desc, reminders.id desc
    limit lim
  ) r;
  return jsonb_build_object('items', payload);
end;
$$;

do $$
declare
  fn regprocedure;
begin
  for fn in
    select p.oid::regprocedure
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname in (
        'clean_text', 'occurrence_date', 'take_idempotency', 'finish_idempotency',
        'require_text', 'require_category', 'require_zone', 'page_limit', 'event_bounds',
        'materialize_series', 'create_work_item', 'update_work_item', 'set_work_item_status',
        'soft_delete_work_item', 'restore_work_item', 'create_event', 'update_event',
        'soft_delete_event', 'create_note', 'update_note', 'soft_delete_note',
        'create_reminder', 'update_reminder', 'soft_delete_reminder',
        'list_work_items', 'list_events_between', 'list_notes', 'list_reminders'
      )
  loop
    execute format('revoke all on function %s from public, anon', fn);
    execute format('grant execute on function %s to authenticated', fn);
  end loop;
end $$;
